// === Tab: mySketch ===
// A RobRed Sketch

let star;
let planet = [];
let mercury;
let venus;
let earth;
let mars;
let stars = []; 

function setup() {
	createCanvas(windowWidth, windowHeight);
	star = new Star();
	mercury = new Planet(100, 0, 8, [175, 170, 170]);
	venus = new Planet(160, PI/4, 20, [245, 222, 179]);
	earth = new Planet(240, PI/2, 21, [65, 105, 225]);
	mars = new Planet(320, PI, 11, [200, 70, 40]);
	planet = [mercury, venus, earth, mars];

	// The orbital eccentricity of a planet measures how much its elliptical orbit deviates from a perfect circle.
	// These are the actual eccentricity values for the first four planets in our solar system.
	mercury.e = 0.2056;
	venus.e = 0.0068;
	earth.e = 0.0167;
	mars.e = 0.0934;

	// These are the experimental planetary orbit speeds and can be tweaked as desired.
	mercury.orbitSpeed = 0.0075;
	venus.orbitSpeed = 0.0052;
	earth.orbitSpeed = 0.0033;
	mars.orbitSpeed = 0.0020;

	// Distribute stars evenly across the initial screen volume
	for (let i = 0; i < 200; i++) {
		let starSize = random(0.5, 3);
		let speedFactor = map(starSize, 0.5, 3, 0.01, 0.06);
		let brightness = map(starSize, 0.5, 3, 80, 255);

		stars.push({
			x: random(-windowWidth / 2 - 30, windowWidth / 2 + 50),
			y: random(-windowHeight / 2 - 50, windowHeight / 2 + 30),
			sz: starSize,
			speed: speedFactor,
			brightness: brightness
		});
	}
}

function draw() {
	background(4, 4, 10);
	translate(width / 2, height / 2);
	noStroke();

	let boundaryX = width / 2 + 50;
	let boundaryY = height / 2 + 50;

	for (let i = 0; i < stars.length; i++) {
		fill(stars[i].brightness);
		ellipse(stars[i].x, stars[i].y, stars[i].sz);

		stars[i].x -= stars[i].speed;
		stars[i].y += stars[i].speed;

		if (stars[i].x < -boundaryX) {
			stars[i].x = boundaryX;
			stars[i].y = random(-boundaryY, boundaryY);
		}

		if (stars[i].y > boundaryY) {
			stars[i].y = -boundaryY;
			stars[i].x = random(-boundaryX, boundaryX);
		}
	}

	star.display();

	for (let i = 0; i < planet.length; i++) {
		planet[i].update();
		planet[i].display();
	}
}

function keyPressed() {
	if (key === 'f' || key === 'F') {
		let fs = fullscreen();
		fullscreen(!fs);
	}
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
	let newBoundaryX = windowWidth / 2;
	let newBoundaryY = windowHeight / 2;
	for (let i = 0; i < stars.length; i++) {
		if (stars[i].x > newBoundaryX || stars[i].x < -newBoundaryX || 
			stars[i].y > newBoundaryY || stars[i].y < -newBoundaryY) {
			stars[i].x = random(-newBoundaryX, newBoundaryX);
			stars[i].y = random(-newBoundaryY, newBoundaryY);
		}
	}
}

// === Tab: tab2 ===
class Star {
	constructor() {
		this.x = 0;
		this.y = 0;
		this.size = 80;
	}

	display() {
		push();
		drawingContext.shadowBlur = 80;
		drawingContext.shadowColor = color(255, 160, 40);
		fill(255, 233, 0);
		noStroke();
		ellipse(this.x, this.y, this.size);
		pop();
	}
}

// === Tab: tab3 ===
class Planet {
	constructor(a, startAngle, size, c) {
		this.a = a;
		this.angle = startAngle;
		this.size = size;
		this.c = c;
		this.orbitSpeed = 0.01;
		this.e = 0.0;
		this.x = 0;
		this.y = 0;
		this.angleToStar = 0;
	}

	update() {
		this.angle += this.orbitSpeed;

		this.x = this.a * cos(this.angle) - (this.a * this.e);
		this.y = this.a * sin(this.angle) * sqrt(1 - (this.e * this.e));

		this.angleToStar = atan2(0 - this.y, 0 - this.x);
	}

	display() {
		push();
		translate(this.x, this.y);
		rotate(this.angleToStar);

		// Layer One: Nightside
		drawingContext.shadowBlur = 0;
		noStroke();
		fill(6, 6, 14);
		arc(0, 0, this.size, this.size, HALF_PI, -HALF_PI);

		// Layer Two: Dayside with Atmospheric Scattering Glow
		if (this.c[0] === 175) {
			drawingContext.shadowBlur = 0;
			drawingContext.shadowOffsetX = 0;
		} else if (this.c[0] === 245) {
			drawingContext.shadowBlur = 40;
			drawingContext.shadowColor = color(this.c[0], this.c[1], this.c[2]);
			drawingContext.shadowOffsetX = 6;
		} else if (this.c[0] === 65) {
			drawingContext.shadowBlur = 15;
			drawingContext.shadowColor = color(0, 140, 255);
			drawingContext.shadowOffsetX = 3;
		} else if (this.c[0] === 200) {
			drawingContext.shadowBlur = 4;
			drawingContext.shadowColor = color(this.c[0], this.c[1], this.c[2]);
			drawingContext.shadowOffsetX = 1;
		}

		drawingContext.shadowOffsetY = 0;
		fill(this.c[0], this.c[1], this.c[2]);
		arc(0, 0, this.size, this.size, -HALF_PI, HALF_PI);
		pop();
	}
}

